// fakeIPASystem is a single fake Redfish system registered with sushy-tools'
// FakeDriver and the corresponding Fake IPA agent it will spawn on power-on.
// Generated by hack/fakeipa-lab-up.sh (not by this package - see
// loadFakeIPASystems), since the lab must exist before the kind cluster is
// created and nothing in this test binary runs that early.
type fakeIPASystem struct {
	UUID string `json:"uuid"`
	Name string `json:"name"`
}

// fakeIPALab bundles the resources started by startFakeIPA.
type fakeIPALab struct {
	fakeIPAConfigDir string
	systems          []fakeIPASystem
}

// Systems returns the fake Redfish systems created by hack/fakeipa-lab-up.sh.
func (l *fakeIPALab) Systems() []fakeIPASystem {
	return l.systems
}

// labBridgeIP is the address of the "baremetal-e2e" libvirt bridge that the
// stock e2e lab (test/e2e/config/vbmctl.yaml.tmpl) and the IRSO Ironic CR
// (test/e2e/data/ironic-standalone-operator/ironic/base/ironic.yaml.tmpl,
// networking.ipAddress: "192.168.222.2") both assume exists. Ironic's own
// provisioning-network configuration needs this bridge regardless of
// FakeDriver/Fake IPA. hack/fakeipa-lab-up.sh creates it (and the veth pair
// to kind) even though it creates no VMs. sushy-tools and Fake IPA run with
// --network host, so binding this address works the same as it does for the
// stock VM-based lab.
const labBridgeIP = "192.168.222.1"

// defaultFakeIPASystemsFile is where hack/fakeipa-lab-up.sh writes the fake
// systems list (see FAKEIPA_LAB_DIR in that script).
const defaultFakeIPASystemsFile = "/tmp/fakeipa-lab/systems.json"

// byteMask isolates a single byte when splitting index into MAC octets.
const byteMask = 0xFF

// Bit-shift widths used to pull the second and third octets out of index in
// macFromIndex.
const (
	thirdOctetShift  = 16
	secondOctetShift = 8
)

// macFromIndex returns a locally-administered MAC address deterministically
// derived from the given index, matching the convention used elsewhere in
// this test suite (e.g. the batch-based scalability tests).
func macFromIndex(index int) string {
	return fmt.Sprintf("02:00:00:%02x:%02x:%02x",
		(index>>thirdOctetShift)&byteMask,
		(index>>secondOctetShift)&byteMask,
		index&byteMask,
	)
}

// newFakeIPABMH creates the BMC credentials secret for sys and returns a
// (not-yet-created) BareMetalHost pointed at it via sushy-tools' FakeDriver.
// imageSpec is nil to leave the host at Available, or set to drive it to
// Provisioned - shared by every FakeIPA scalability test (batch, cumulative-
// ramp, and concurrent-round alike) so the BMH shape stays consistent.
func newFakeIPABMH(ctx context.Context, cl client.Client, namespace, hostName string, index int, sys fakeIPASystem, imageSpec *metal3api.Image) metal3api.BareMetalHost {
	secretName := hostName + "-creds"
	CreateSecret(ctx, cl, namespace, secretName, map[string]string{
		"username": "admin",
		"password": "password",
	})

	return metal3api.BareMetalHost{
		ObjectMeta: metav1.ObjectMeta{
			Name:      hostName,
			Namespace: namespace,
		},
		Spec: metal3api.BareMetalHostSpec{
			Online: true,
			BMC: metal3api.BMCDetails{
				Address:                        fmt.Sprintf("redfish+http://%s/redfish/v1/Systems/%s", net.JoinHostPort(labBridgeIP, "8000"), sys.UUID),
				CredentialsName:                secretName,
				DisableCertificateVerification: true,
			},
			BootMACAddress:        macFromIndex(index),
			BootMode:              metal3api.UEFI,
			AutomatedCleaningMode: metal3api.CleaningModeDisabled,
			InspectionMode:        metal3api.InspectionModeDisabled,
			Image:                 imageSpec,
		},
	}
}

// cleanupBMHsParallel deletes every BMH in namespace with a single bulk
// request (DeleteBmhsInNamespace), then polls with one List call per tick
// (rather than one Get per host) until they're all gone or timeout elapses,
// before deleting the per-host credential secrets concurrently. This replaces
// looping CleanupBMH per host - which deletes and waits for one host fully
// before even starting the next - so that BMO/Ironic can process every
// host's finalizer clearing concurrently instead of being serialized by the
// test's own one-at-a-time waiting. Used by every FakeIPA scalability test's
// cleanup (AfterEach, and each concurrent-round's end-of-round teardown).
const cleanupPollInterval = 2 * time.Second

func cleanupBMHsParallel(ctx context.Context, cl client.Client, namespace string, bmhs []metal3api.BareMetalHost, timeout time.Duration) {
	if len(bmhs) == 0 {
		return
	}

	DeleteBmhsInNamespace(ctx, cl, namespace)

	deadline := time.Now().Add(timeout)
	for {
		var list metal3api.BareMetalHostList
		if err := cl.List(ctx, &list, client.InNamespace(namespace)); err == nil && len(list.Items) == 0 {
			break
		}
		if time.Now().After(deadline) {
			Logf("WARNING: BMHs still remain in %s after %s", namespace, timeout)
			break
		}
		time.Sleep(cleanupPollInterval)
	}

	var wg sync.WaitGroup
	for i := range bmhs {
		wg.Add(1)
		go func(bmh *metal3api.BareMetalHost) {
			defer wg.Done()
			DeleteSecretIfExists(ctx, cl, bmh.Namespace, bmh.Spec.BMC.CredentialsName)
		}(&bmhs[i])
	}
	wg.Wait()
}

// loadFakeIPASystems reads the fake systems list written by
// hack/fakeipa-lab-up.sh, which must have been run (standing up the
// baremetal-e2e bridge, image server, and sushy-tools FakeDriver container)
// before `make test-e2e` was invoked.
func loadFakeIPASystems(path string) ([]fakeIPASystem, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("failed to read fake systems file %q (did you run hack/fakeipa-lab-up.sh first?): %w", path, err)
	}
	var systems []fakeIPASystem
	if err := json.Unmarshal(data, &systems); err != nil {
		return nil, fmt.Errorf("failed to parse fake systems file %q: %w", path, err)
	}
	return systems, nil
}

// writeFakeIPAConfig renders the Python config file Fake IPA loads via
// --config, pointing it at the Ironic API this e2e run exposes. certPath and
// keyPath (inside the container) give Fake IPA a TLS identity: Ironic's
// agent API rejects heartbeats with "TLS is required by configuration" if
// the agent announces a plain-http callback URL, so Fake IPA must serve
// itself over HTTPS like a real IPA would.
//
// FAKE_IPA_MIN_BOOT_TIME/MAX_BOOT_TIME default to 180/240s upstream (see
// fake_ipa/fake_agent.py), simulating realistic hardware boot latency. For
// our scale-ceiling testing that delay just slows down iteration without
// adding signal, so it's shortened here; real-hardware-realistic timing can
// be restored later if actual boot-latency-under-load behavior is needed.
const fakeIPAConfigFileMode = 0o600

func writeFakeIPAConfig(path, ironicURL, advertiseIP, certPath, keyPath string) error {
	tmpl := `FAKE_IPA_API_URL = %q
FAKE_IPA_ADVERTISE_ADDRESS_IP = %q
FAKE_IPA_INSECURE = True
FAKE_IPA_MIN_BOOT_TIME = 5
FAKE_IPA_MAX_BOOT_TIME = 10
FAKE_IPA_CERTFILE = %q
FAKE_IPA_KEYFILE = %q
`
	content := fmt.Sprintf(tmpl, ironicURL, advertiseIP, certPath, keyPath)
	return os.WriteFile(path, []byte(content), fakeIPAConfigFileMode)
}

// generateSelfSignedCert writes a throwaway self-signed TLS cert/key pair to
// certPath/keyPath, used only so Fake IPA can serve its agent API over
// HTTPS (see writeFakeIPAConfig).
func generateSelfSignedCert(ctx context.Context, certPath, keyPath string) error {
	cmd := exec.CommandContext(ctx, "openssl", "req", "-x509", "-newkey", "rsa:2048",
		"-keyout", keyPath, "-out", certPath,
		"-days", "1", "-nodes",
		"-subj", "/CN=fake-ipa")
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("failed to generate self-signed cert: %w\noutput:\n%s", err, out)
	}
	return nil
}

// fakeIPAContainerName is the fixed name used for the Fake IPA container so
// Cleanup can find and remove it without tracking extra state.
const fakeIPAContainerName = "scale-fakeipa"

// startFakeIPA loads the fake systems list produced by
// hack/fakeipa-lab-up.sh and starts the Fake IPA container (plain docker
// container, not managed by vbmctl) pointed at ironicURL. Unlike the
// network/image-server/sushy-tools lab, Fake IPA doesn't need to exist
// before the kind cluster is created - only before any BMH is powered on -
// so it's safe to start per-spec from BeforeEach.
func startFakeIPA(ctx context.Context, systemsFile, fakeIPAImage, ironicURL string) (*fakeIPALab, error) {
	systems, err := loadFakeIPASystems(systemsFile)
	if err != nil {
		return nil, err
	}

	workDir, err := os.MkdirTemp("", "fakeipa-")
	if err != nil {
		return nil, fmt.Errorf("failed to create work dir: %w", err)
	}

	certPath := filepath.Join(workDir, "fake-ipa.crt")
	keyPath := filepath.Join(workDir, "fake-ipa.key")
	if err := generateSelfSignedCert(ctx, certPath, keyPath); err != nil {
		return nil, err
	}

	const containerCertPath = "/app/certs/tls.crt"
	const containerKeyPath = "/app/certs/tls.key"

	fakeIPAConfigPath := filepath.Join(workDir, "fake-ipa.conf")
	if err := writeFakeIPAConfig(fakeIPAConfigPath, ironicURL, labBridgeIP, containerCertPath, containerKeyPath); err != nil {
		return nil, err
	}

	// Remove any stale container from a previous aborted run before starting.
	_ = exec.CommandContext(ctx, "docker", "rm", "-f", fakeIPAContainerName).Run()

	runCmd := exec.CommandContext(ctx, "docker", "run", "-d",
		"--name", fakeIPAContainerName,
		"--network", "host",
		"-v", fakeIPAConfigPath+":/app/conf.py:Z",
		"-v", certPath+":"+containerCertPath+":Z",
		"-v", keyPath+":"+containerKeyPath+":Z",
		fakeIPAImage)
	if out, err := runCmd.CombinedOutput(); err != nil {
		return nil, fmt.Errorf("failed to start Fake IPA container: %w\noutput:\n%s", err, out)
	}

	return &fakeIPALab{
		fakeIPAConfigDir: workDir,
		systems:          systems,
	}, nil
}

// Cleanup stops the Fake IPA container. It does not tear down the
// network/image-server/sushy-tools lab - that is shared across the whole
// suite run and torn down separately via hack/fakeipa-lab-down.sh.
func (l *fakeIPALab) Cleanup(ctx context.Context) {
	if l == nil {
		return
	}
	if out, err := exec.CommandContext(ctx, "docker", "rm", "-f", fakeIPAContainerName).CombinedOutput(); err != nil {
		Logf("WARNING: failed to remove Fake IPA container: %v\n%s", err, out)
	}
	if l.fakeIPAConfigDir != "" {
		_ = os.RemoveAll(l.fakeIPAConfigDir)
	}
}

// sampleIronicMemoryMB finds the Ironic pod (by name heuristic, since the
// exact label applied by ironic-standalone-operator wasn't confirmed ahead
// of time - see docs/e2e-scalability-fakeipa.md) in namespace and returns
// its current cgroup memory usage in MiB.
const bytesPerMiB = 1024 * 1024

func sampleIronicMemoryMB(ctx context.Context, namespace string) (float64, error) {
	clientset := clusterProxy.GetClientSet()

	pods, err := clientset.CoreV1().Pods(namespace).List(ctx, metav1.ListOptions{})
	if err != nil {
		return 0, fmt.Errorf("failed to list pods in %s: %w", namespace, err)
	}

	var podName string
	for _, pod := range pods.Items {
		if strings.Contains(pod.Name, "ironic") {
			podName = pod.Name
			break
		}
	}
	if podName == "" {
		return 0, fmt.Errorf("no ironic pod found in namespace %s", namespace)
	}

	// Try cgroup v2 first, fall back to v1.
	for _, path := range []string{"/sys/fs/cgroup/memory.current", "/sys/fs/cgroup/memory/memory.usage_in_bytes"} {
		cmd := exec.CommandContext(ctx, "kubectl", "exec", "-n", namespace, podName, "--", "cat", path)
		out, err := cmd.Output()
		if err != nil {
			continue
		}
		var bytesUsed float64
		if _, scanErr := fmt.Sscanf(strings.TrimSpace(string(out)), "%f", &bytesUsed); scanErr == nil {
			return bytesUsed / bytesPerMiB, nil
		}
	}

	return 0, fmt.Errorf("could not read cgroup memory usage for pod %s", podName)
}
